package com.travelbird.ai.service;
import com.travelbird.common.enums.*;
import static org.mockito.Mockito.*;import com.travelbird.ai.client.AiRecommendationClient;import com.travelbird.ai.dto.internal.*;import com.travelbird.ai.entity.AiRequestType;import com.travelbird.global.error.*;import com.travelbird.trip.entity.*;import java.time.LocalDate;import java.util.List;import org.junit.jupiter.api.Test;
class AiDispatcherConflictTest{@Test void differentFingerprintIsRecordedAsNonRetryableConflict(){var client=mock(AiRecommendationClient.class);var transitions=mock(AiJobTransitionService.class);doThrow(new BusinessException(ErrorCode.AI_JOB_ID_CONFLICT)).when(transitions).prepare(7L,"different");var dispatcher=new AiRecommendationDispatcher(client,transitions);var request=new RecommendationJobRequest(7L,AiRequestType.GENERAL,"11110",LocalDate.of(2026,10,1),LocalDate.of(2026,10,2),CompanionType.SOLO,List.of(TravelTheme.FOOD),Pace.NORMAL,List.of(),List.of(),List.of(),true);dispatcher.dispatchSafely(new AiDispatchRequested(request,new PlaceSyncRequest(List.of()),"different"));verify(transitions).failed(eq(7L),eq(AiJobFailureCode.AI_JOB_ID_CONFLICT),anyString(),eq(false));verifyNoInteractions(client);}}

